import subprocess
import os
import shutil
from glob import glob
def task_func(src_folder, dst_folder):
    if not os.path.isdir(src_folder) or not os.path.isdir(dst_folder):
        return {'success': False, 'message': 'Source or destination folder does not exist', 'failed_files': []}
    failed_files = []
    for file_path in glob(os.path.join(src_folder, '*')):
        if os.path.isfile(file_path):
            compressed_file = file_path + '.gz'
            dest_path = os.path.join(dst_folder, os.path.basename(compressed_file))
            try:
                result = subprocess.run(['gzip', '-k', file_path], capture_output=True, text=True)
                if result.returncode == 0:
                    shutil.move(compressed_file, dest_path)
                else:
                    failed_files.append(os.path.basename(file_path))
                    if os.path.exists(compressed_file):
                        os.remove(compressed_file)
            except Exception:
                failed_files.append(os.path.basename(file_path))
                if os.path.exists(compressed_file):
                    os.remove(compressed_file)
    success = len(failed_files) == 0
    message = 'All files compressed and moved successfully' if success else f'Failed to process {len(failed_files)} file(s)'
    return {'success': success, 'message': message, 'failed_files': failed_files}
